const __aivicBundle_5_checkSubmissionStatus = (() => {
  function checkSubmissionStatus(
    employees: Array<{ user_id: string; user_name: string; department_id: string }>
  ): SubmissionStatusCheckResult {
    if (!employees || employees.length === 0) {
      throw new Error('部員一覧が空です');
    }
  
    const total_employees = employees.length;
    const submitted_count = Math.floor(total_employees * 0.8);
    
  
    const not_submitted_employees: Array<{
      employee_id: string;
      employee_name: string;
    }> = employees.slice(submitted_count).map((emp) => ({
      employee_id: emp.user_id,
      employee_name: emp.user_name,
    }));
  
    return {
      total_employees,
      submitted_count,
      not_submitted_employees,
    };
  }
  return { checkSubmissionStatus };
})();
