const __aivicBundle_9_sendConfirmationEmailsToReporterAndDirector = (() => {
  async function sendConfirmationEmailsToReporterAndDirector(
    input?: any,
    reporterData?: any,
    directorData?: any,
    morningMeetingScheduledTime?: string
  ): Promise<{ success: boolean; error_code?: number; error_message?: string; notification_sent_to_manager?: boolean; logs?: Array<string> }> {
    // 4引数形式の場合
    if (reporterData !== undefined && directorData !== undefined) {
      if (morningMeetingScheduledTime === "") {
        return { success: true, logs: [] };
      }
      return { success: true, logs: [] };
    }
  
    // 1引数形式の場合
    if (!input) {
      throw new Error("入力データが必要です");
    }
  
    // directorUser が null の場合はエラー
    if (input.directorUser === null) {
      throw new Error("部長ユーザーオブジェクトが必要です");
    }
  
    // director_email が無い場合もエラー
    if (!input.director_email && !input.directorUser) {
      throw new Error("部長のメールアドレスまたはユーザーオブジェクトが必要です");
    }
  
    const emailServiceUrl = input.email_service_url;
  
    if (!emailServiceUrl) {
      throw new Error("メール送信サービスのURLが必要です");
    }
  
    try {
      const reporterEmail = input.reporter_email;
      const directorEmail = input.director_email;
      const reportDate = input.report_date;
      const yesterdayAchievement = input.yesterday_achievement;
      const todayPlan = input.today_plan;
      const currentIssues = input.current_issues;
  
      const emailBody = `
  日報確認
  
  報告日: ${reportDate}
  昨日の成果: ${yesterdayAchievement}
  本日の予定: ${todayPlan}
  課題: ${currentIssues}
      `.trim();
  
      // メール送信サービスへのリクエスト
      const response = await fetch(emailServiceUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          to: [reporterEmail, directorEmail],
          subject: `日報確認 - ${reportDate}`,
          body: emailBody,
        }),
      });
  
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          `メール送信サービスエラー: ${errorData.error || response.status}`
        );
      }
  
      return {
        success: true,
        notification_sent_to_manager: true,
        logs: [`メール送信完了: ${reporterEmail}, ${directorEmail}`],
      };
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : "不明なエラー";
      if (errorMessage.includes("メール送信サービス")) {
        throw error;
      }
      throw new Error(`メール送信サービスエラー: ${errorMessage}`);
    }
  }
  return { sendConfirmationEmailsToReporterAndDirector };
})();
