/* AIVIC_FUNCTION_BUNDLE_START owner=formatAndDisplayReportList exports=formatAndDisplayReportList */
const __aivicBundle_11_formatAndDisplayReportList = (() => {
  function formatAndDisplayReportList(reportList: Array<any>): ReportListDisplayData {
    if (!Array.isArray(reportList) || reportList.length === 0) {
      throw new Error('日報リストが空です');
    }
  
    const reports: Array<{
      user_id: string;
      user_name: string;
      yesterday_achievement: string;
      today_plan: string;
      current_issues: string;
      status: 'submitted' | 'missing';
    }> = [];
    const missingMembers: Array<string> = [];
    let totalSubmitted = 0;
    let totalMissing = 0;
  
    for (const report of reportList) {
      const formattedReport = {
        user_id: report.user_id || '',
        user_name: report.user_name || '',
        yesterday_achievement: report.yesterday_achievement || '',
        today_plan: report.today_plan || '',
        current_issues: report.current_issues || '',
        status: (report.status === 'submitted' ? 'submitted' : 'missing') as 'submitted' | 'missing',
      };
  
      reports.push(formattedReport);
  
      if (formattedReport.status === 'submitted') {
        totalSubmitted++;
      } else {
        totalMissing++;
        missingMembers.push(formattedReport.user_name);
      }
    }
  
    return {
      reports,
      missingMembers,
      totalSubmitted,
      totalMissing,
    };
  }
  return { formatAndDisplayReportList };
})();
export const formatAndDisplayReportList = __aivicBundle_11_formatAndDisplayReportList.formatAndDisplayReportList;
