const __aivicBundle_26_detectUnreportedMembers = (() => {
  function detectUnreportedMembers(params: {
    meeting_date: Date;
    reported_member_list: Array<{ user_id: string; user_name: string; submitted_at: Date | string }>;
    all_member_list: Array<{ user_id: string; user_name: string; department_id: string }>;
    target_date_str: string;
  }): {
    unreported_member_count: number;
    reported_member_count: number;
    unreported_members: Array<{ user_id: string; user_name: string; status_message: string }>;
    reported_members: Array<{ user_id: string; user_name: string }>;
  } {
    if (params["meeting_date"] === undefined || params["meeting_date"] === null) { throw new Error("meeting_date is required"); }
    if (params["target_date_str"] === undefined || params["target_date_str"] === null) { throw new Error("target_date_str is required"); }
    const { reported_member_list, all_member_list } = params;
  
    const reported_user_ids = new Set(reported_member_list.map((m) => m.user_id));
  
    const reported_members: Array<{ user_id: string; user_name: string }> = [];
    const unreported_members: Array<{ user_id: string; user_name: string; status_message: string }> = [];
  
    for (const member of all_member_list) {
      if (reported_user_ids.has(member.user_id)) {
        reported_members.push({
          user_id: member.user_id,
          user_name: member.user_name,
        });
      } else {
        unreported_members.push({
          user_id: member.user_id,
          user_name: member.user_name,
          status_message: '朝会当日の報告なし',
        });
      }
    }
  
    return {
      unreported_member_count: unreported_members.length,
      reported_member_count: reported_members.length,
      unreported_members,
      reported_members,
    };
  }
  return { detectUnreportedMembers };
})();
