/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportSubmissionTime exports=validateReportSubmissionTime */
const __aivicBundle_48_validateReportSubmissionTime = (() => {
  function validateReportSubmissionTime(input: {
    userId: string;
    currentTimeJst: Date;
    timezoneId: string;
  }): {
    isSubmissionTarget: boolean;
    targetDate: string;
    utcTime: string;
    jstTime: string;
    monthBoundaryHandled: boolean;
  } {
    const { userId, currentTimeJst, timezoneId } = input;
  
    // JST時刻を ISO 8601 形式で取得
    
    
    // JST時刻から日付を抽出（YYYY-MM-DD形式）
    // currentTimeJst は既に JST で解釈されているため、その日付を targetDate とする
    const jstDateParts = currentTimeJst.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      timeZone: timezoneId,
    }).split('/');
    const targetDate = `${jstDateParts[0]}-${jstDateParts[1]}-${jstDateParts[2]}`;
  
    // UTC時刻を計算
    // JST は UTC+9 なので、JST時刻から9時間を引く
    const utcTime = new Date(currentTimeJst.getTime() - 9 * 60 * 60 * 1000);
    const utcTimeString = utcTime.toISOString();
  
    // JST時刻を ISO 8601 形式で表現（+09:00 オフセット付き）
    const jstYear = currentTimeJst.getFullYear();
    const jstMonth = String(currentTimeJst.getMonth() + 1).padStart(2, '0');
    const jstDay = String(currentTimeJst.getDate()).padStart(2, '0');
    const jstHours = String(currentTimeJst.getHours()).padStart(2, '0');
    const jstMinutes = String(currentTimeJst.getMinutes()).padStart(2, '0');
    const jstSeconds = String(currentTimeJst.getSeconds()).padStart(2, '0');
    const jstTimeString = `${jstYear}-${jstMonth}-${jstDay}T${jstHours}:${jstMinutes}:${jstSeconds}+09:00`;
  
    // 月境界処理フラグ：JST と UTC で日付が異なる場合、月をまたいでいる
    const utcDateParts = utcTime.toISOString().split('T')[0];
    const monthBoundaryHandled = targetDate !== utcDateParts;
  
    // 報告対象判定：userId が存在し、現在時刻が有効な場合は報告対象
    const isSubmissionTarget = !!userId && currentTimeJst instanceof Date && !isNaN(currentTimeJst.getTime());
  
    return {
      isSubmissionTarget,
      targetDate,
      utcTime: utcTimeString,
      jstTime: jstTimeString,
      monthBoundaryHandled,
    };
  }
  return { validateReportSubmissionTime };
})();
