const __aivicBundle_49_sendConfirmationEmailsOnReporting = (() => {
  function sendConfirmationEmailsOnReporting(
    submission_user_id: string,
    submission_timestamp: Date,
    submission_user_email: string,
    department_head_email: string,
    submission_content: {
      yesterday_achievement: string;
      today_plan: string;
      current_issues: string;
    },
    deadline_start_time: Date,
    deadline_end_time: Date,
    email_send_hook: (to_email: string, subject: string, body: string) => void
  ): {
    is_within_deadline: boolean;
    is_nanosecond_truncated: boolean;
    sent_at_timestamp: Date;
    email_delivery_status: 'success' | 'failure';
  } {
    if (submission_user_id === undefined || submission_user_id === null) { throw new Error("submission_user_id is required"); }
    const submissionTimeMs = submission_timestamp.getTime();
    const deadlineStartMs = deadline_start_time.getTime();
    const deadlineEndMs = deadline_end_time.getTime();
  
    const isWithinDeadline = submissionTimeMs >= deadlineStartMs && submissionTimeMs <= deadlineEndMs;
  
    const isoString = submission_timestamp.toISOString();
    const hasNanoseconds = isoString.includes('.') && isoString.split('.')[1].length > 6;
  
    let emailDeliveryStatus: 'success' | 'failure' = 'failure';
  
    if (isWithinDeadline) {
      try {
        const emailSubject = '報告内容確認メール';
        const emailBody = `報告内容確認\n\n昨日の成果: ${submission_content.yesterday_achievement}\n本日の予定: ${submission_content.today_plan}\n現在の課題: ${submission_content.current_issues}`;
  
        email_send_hook(submission_user_email, emailSubject, emailBody);
        email_send_hook(department_head_email, emailSubject, emailBody);
  
        emailDeliveryStatus = 'success';
      } catch {
        emailDeliveryStatus = 'failure';
      }
    }
  
    return {
      is_within_deadline: isWithinDeadline,
      is_nanosecond_truncated: hasNanoseconds,
      sent_at_timestamp: submission_timestamp,
      email_delivery_status: emailDeliveryStatus
    };
  }
  return { sendConfirmationEmailsOnReporting };
})();
