/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportCompleteness exports=validateReportCompleteness */
const __aivicBundle_52_validateReportCompleteness = (() => {
  function validateReportCompleteness(reportData: {
    yesterday_accomplishments?: string;
    today_plan?: string;
    current_challenges?: string;
    yesterday_achievement?: string;
    today_plan_text?: string;
    current_issue?: string;
    issue_held?: string;
  }): {
    is_complete: boolean;
    missing_fields: string[];
    validation_message?: string;
  } {
    const missing_fields: string[] = [];
  
    // Normalize field names to handle multiple naming conventions
    const yesterday =
      reportData.yesterday_accomplishments ??
      reportData.yesterday_achievement ??
      undefined;
    const today =
      reportData.today_plan ?? reportData.today_plan_text ?? undefined;
    const challenges =
      reportData.current_challenges ??
      reportData.current_issue ??
      reportData.issue_held ??
      undefined;
  
    // Check if yesterday_accomplishments is missing or empty
    if (!yesterday || yesterday.trim() === '') {
      missing_fields.push('yesterday_accomplishments');
    }
  
    // Check if today_plan is missing or empty
    if (!today || today.trim() === '') {
      missing_fields.push('today_plan');
    }
  
    // Check if current_challenges is missing or empty
    if (challenges === undefined || challenges === null || challenges.trim() === '') {
      // Determine which field name was actually provided to report correctly
      if (reportData.issue_held !== undefined) {
        missing_fields.push('issue_held');
      } else if (reportData.current_issue !== undefined) {
        missing_fields.push('current_issue');
      } else {
        missing_fields.push('current_challenges');
      }
    }
  
    const is_complete = missing_fields.length === 0;
  
    const result: {
      is_complete: boolean;
      missing_fields: string[];
      validation_message?: string;
    } = {
      is_complete,
      missing_fields,
    };
  
    if (!is_complete) {
      result.validation_message = 'Report content is incomplete';
    }
  
    return result;
  }
  return { validateReportCompleteness };
})();
export const validateReportCompleteness = __aivicBundle_52_validateReportCompleteness.validateReportCompleteness;
