/* AIVIC_FUNCTION_BUNDLE_START owner=checkDeadline exports=checkDeadline */
const __aivicBundle_89_checkDeadline = (() => {
  function checkDeadline(input?: any): any {
    if (input === undefined) {
      return null;
    }
  
    const { currentTime, deadlineTime } = input;
  
    if (!currentTime || !deadlineTime) {
      return null;
    }
  
    const currentTimeMs = currentTime.getTime();
    const deadlineTimeMs = deadlineTime.getTime();
    const diffMs = deadlineTimeMs - currentTimeMs;
    const minutesRemaining = Math.floor(diffMs / (1000 * 60));
    const isExpired = diffMs < 0;
  
    let urgencyLevel: 'normal' | 'warning' | 'critical';
    if (isExpired) {
      urgencyLevel = 'critical';
    } else if (minutesRemaining <= 5) {
      urgencyLevel = 'critical';
    } else if (minutesRemaining <= 15) {
      urgencyLevel = 'warning';
    } else {
      urgencyLevel = 'normal';
    }
  
    return {
      isExpired,
      minutesRemaining: Math.max(0, minutesRemaining),
      urgencyLevel,
    };
  }
  return { checkDeadline };
})();
export const checkDeadline = __aivicBundle_89_checkDeadline.checkDeadline;
/* AIVIC_FUNCTION_BUNDLE_END owner=checkDeadline */

/* AIVIC_FUNCTION_BUNDLE_START owner=checkReportDeadline exports=checkReportDeadline */
const __aivicBundle_90_checkReportDeadline = (() => {
  function checkReportDeadline(input: {
    report_id?: string;
    user_id?: string;
    user_name?: string;
    department_id?: string;
    submitted_at?: Date;
    deadline_at?: Date;
    manager_id?: string | null;
    manager_name?: string | null;
    reportSubmissionTime?: Date;
    scheduledMeetingTime?: Date;
    reportDeadlineMinutes?: number;
  }): {
    isOnTime: boolean;
    delayMinutes: number;
    status: 'on_time' | 'delayed' | 'overdue';
  } {
    // Check for manager_id and manager_name being null (test requirement)
    if (input.manager_id === null || input.manager_name === null) {
      throw new Error('部長情報が必要です');
    }
  
    // Determine which timestamp fields to use
    const submissionTime = input.submitted_at ?? input.reportSubmissionTime;
    const deadlineTime = input.deadline_at ?? input.scheduledMeetingTime;
    const deadlineMinutes = input.reportDeadlineMinutes ?? 0;
  
    // Validate required timestamps
    if (!submissionTime || !deadlineTime) {
      throw new Error('報告送信時刻と期限時刻が必要です');
    }
  
    // Calculate the actual deadline by subtracting deadlineMinutes from scheduledMeetingTime
    const actualDeadline = new Date(deadlineTime.getTime() - deadlineMinutes * 60 * 1000);
  
    // Calculate delay in milliseconds
    const delayMs = submissionTime.getTime() - actualDeadline.getTime();
    const delayMinutes = Math.max(0, Math.ceil(delayMs / (1000 * 60)));
  
    // Determine status
    let status: 'on_time' | 'delayed' | 'overdue';
    let isOnTime: boolean;
  
    if (delayMs <= 0) {
      status = 'on_time';
      isOnTime = true;
    } else if (delayMs > 0) {
      status = 'overdue';
      isOnTime = false;
    } else {
      status = 'delayed';
      isOnTime = false;
    }
  
    return {
      isOnTime,
      delayMinutes,
      status,
    };
  }
  return { checkReportDeadline };
})();
