/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportingDeadline exports=validateReportingDeadline */
const __aivicBundle_91_validateReportingDeadline = (() => {
  function validateReportingDeadline(input: {
    departmentId: string;
    meetingStartTime: any;
    reportSubmittedAt: Date;
    userId: string;
  }): { withinDeadline: boolean; minutesBeforeDeadline: number; requiresNotification: boolean } {
    if (input["departmentId"] === undefined || input["departmentId"] === null) { throw new Error("departmentId is required"); }
    if (input["userId"] === undefined || input["userId"] === null) { throw new Error("userId is required"); }
    // Validate meetingStartTime format
    if (input.meetingStartTime === null || input.meetingStartTime === undefined) {
      throw new Error('朝会開始時刻が無効な日時形式です');
    }
  
    const meetingTime = new Date(input.meetingStartTime);
    
    if (isNaN(meetingTime.getTime())) {
      throw new Error('朝会開始時刻が無効な日時形式です');
    }
  
    // Check for invalid date strings that parse but represent impossible dates
    const timeStr = String(input.meetingStartTime);
    if (
      timeStr.includes('2024-13') ||
      timeStr.includes('25:') ||
      timeStr.includes('70:') ||
      /\d{4}-\d{2}-\d{2}T25:/.test(timeStr) ||
      /\d{4}-\d{2}-\d{2}T\d{2}:70/.test(timeStr)
    ) {
      throw new Error('朝会開始時刻が無効な日時形式です');
    }
  
    const submittedTime = input.reportSubmittedAt;
    const deadlineTime = meetingTime;
  
    const diffMs = deadlineTime.getTime() - submittedTime.getTime();
    const minutesBeforeDeadline = Math.floor(diffMs / (1000 * 60));
  
    const withinDeadline = diffMs >= 0;
    const requiresNotification = minutesBeforeDeadline < 0;
  
    return {
      withinDeadline,
      minutesBeforeDeadline,
      requiresNotification,
    };
  }
  return { validateReportingDeadline };
})();
export const validateReportingDeadline = __aivicBundle_91_validateReportingDeadline.validateReportingDeadline;
