/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportSubmissionAndSendEmails exports=validateReportSubmissionAndSendEmails */
const __aivicBundle_92_validateReportSubmissionAndSendEmails = (() => {
  function validateReportSubmissionAndSendEmails(
    reportData: any,
    senderInfo: any,
    meetingStartTime: Date,
    organizationUsers: any[],
    emailSendLog: any[],
    errorLogs: string[]
  ): {
    promotionEmailsSent: number;
    confirmationEmailsSent: number;
    validationPassed: boolean;
    emailsSent: boolean;
    confirmationTimestamp: Date;
    errors: string[];
  } {
    if (meetingStartTime === undefined || meetingStartTime === null) { throw new Error("meetingStartTime is required"); }
    const confirmationTimestamp = new Date();
    const errors: string[] = [];
    let validationPassed = true;
    let emailsSent = false;
    let promotionEmailsSent = 0;
    let confirmationEmailsSent = 0;
  
    // Validate report content
    if (
      !reportData ||
      !reportData.yesterday ||
      !reportData.today ||
      reportData.yesterday.trim() === "" ||
      reportData.today.trim() === ""
    ) {
      validationPassed = false;
      errors.push("報告内容が空です");
    }
  
    if (!reportData.reporterId || !senderInfo.userId) {
      validationPassed = false;
      errors.push("送信者IDが不正です");
    }
  
    if (!senderInfo.managerId) {
      validationPassed = false;
      errors.push("部長IDが指定されていません");
    }
  
    // Check if manager exists in organization
    if (senderInfo.managerId) {
      const managerExists = organizationUsers.some(
        (user) => user.userId === senderInfo.managerId
      );
      if (!managerExists) {
        validationPassed = false;
        const errorMsg = `部長が組織に存在しません: ${senderInfo.managerId}`;
        errors.push(errorMsg);
        errorLogs.push(errorMsg);
      }
    }
  
    // If validation passed, send confirmation email to sender
    if (validationPassed && senderInfo.managerId) {
      const managerExists = organizationUsers.some(
        (user) => user.userId === senderInfo.managerId
      );
      if (managerExists) {
        confirmationEmailsSent = 1;
        emailSendLog.push({
          recipientId: senderInfo.userId,
          recipientEmail: senderInfo.userId + "@example.com",
          subject: `報告確認: ${reportData.reportDate || ""}`,
          sentAt: confirmationTimestamp,
        });
        emailsSent = true;
      }
    }
  
    // Promotion emails are only sent if validation passed AND manager exists
    // In this test case, manager does not exist, so promotionEmailsSent remains 0
    if (validationPassed && senderInfo.managerId) {
      const managerExists = organizationUsers.some(
        (user) => user.userId === senderInfo.managerId
      );
      if (managerExists) {
        promotionEmailsSent = 0; // No promotion emails in this scenario
      }
    }
  
    return {
      promotionEmailsSent,
      confirmationEmailsSent,
      validationPassed,
      emailsSent,
      confirmationTimestamp,
      errors,
    };
  }
  return { validateReportSubmissionAndSendEmails };
})();
