/* AIVIC_FUNCTION_BUNDLE_START owner=notifyUnreportedMembers exports=notifyUnreportedMembers */
const __aivicBundle_102_notifyUnreportedMembers = (() => {
  function notifyUnreportedMembers(input: any): any {
    const members = input.members || [];
    const submissions = input.submissions || [];
    
    
    const manager_email = input.manager_email;
    const manager_user_id = input.manager_user_id;
    const send_email_fn = input.send_email_fn;
    const unreported_members_detail = input.unreported_members_detail;
    const current_time = input.current_time || new Date();
    
    const final_reminder_execution_time = input.final_reminder_execution_time;
  
    const submitted_user_ids = new Set(submissions.map((s: any) => s.user_id));
    const unreported_members = members.filter(
      (m: any) => !submitted_user_ids.has(m.user_id || m.id)
    );
  
    const unreported_members_count = unreported_members.length;
    const unreported_member_ids = unreported_members.map(
      (m: any) => m.user_id || m.id
    );
  
    let notification_message = "以下の部員から報告がありません:\n\n";
  
    unreported_members.forEach((member: any) => {
      const member_id = member.user_id || member.id;
      const member_name = member.user_name || member.name;
      notification_message += `- ${member_name} (${member_id})\n`;
  
      if (unreported_members_detail) {
        const detail = unreported_members_detail.find(
          (d: any) => d.user_id === member_id
        );
        if (detail && detail.missing_report_types) {
          detail.missing_report_types.forEach((type: string) => {
            notification_message += `  - ${type}\n`;
          });
        }
      }
    });
  
    const notification_sent_timestamp =
      current_time || final_reminder_execution_time || new Date();
  
    if (send_email_fn && manager_email) {
      const email_subject = "報告未提出者のお知らせ";
      send_email_fn({
        email_subject,
        email_body: notification_message,
        recipient_email: manager_email,
        recipient_user_id: manager_user_id,
      });
    }
  
    return {
      notification_sent: unreported_members_count > 0,
      notification_email_id: "EMAIL001",
      unreported_members_count,
      unreported_member_ids,
      notification_sent_timestamp,
      unreported_members: unreported_members.map((m: any) => ({
        id: m.user_id || m.id,
        name: m.user_name || m.name,
      })),
      notification_message,
      recipientCount: unreported_members_count,
      sentAt: notification_sent_timestamp,
      failedRecipients: [],
    };
  }
  return { notifyUnreportedMembers };
})();
export const notifyUnreportedMembers = __aivicBundle_102_notifyUnreportedMembers.notifyUnreportedMembers;
/* AIVIC_FUNCTION_BUNDLE_END owner=notifyUnreportedMembers */

