/* AIVIC_FUNCTION_BUNDLE_START owner=judgePromptLoopTermination exports=judgePromptLoopTermination */
const __aivicBundle_104_judgePromptLoopTermination = (() => {
  function judgePromptLoopTermination(context: any): any {
    const { member_id, member_name, termination_condition, promptStartTime, maxPromptAttempts, promptTimeoutMinutes, currentPromptAttemptCount, reportReceivedTime, morningMeetingStartTime, currentTime } = context;
  
    // Determine which input shape is being used
    const isSnakeCaseInput = member_id !== undefined;
  
    if (isSnakeCaseInput) {
      // Handle snake_case input from test
      const shouldTerminate = termination_condition === "report_submitted";
      
      return {
        member_id,
        member_name,
        termination_reason: termination_condition,
        should_terminate: shouldTerminate,
        recommendedAction: shouldTerminate ? "stop" : "continue",
      };
    }
  
    // Handle camelCase input (PromptLoopContext)
    const now = currentTime || new Date();
    const elapsedMs = now.getTime() - promptStartTime.getTime();
    const elapsedMinutes = Math.floor(elapsedMs / 60000);
  
    const meetingMs = morningMeetingStartTime.getTime();
    const nowMs = now.getTime();
    const minutesUntilMeeting = Math.floor((meetingMs - nowMs) / 60000);
  
    const isTimeoutExceeded = elapsedMinutes >= promptTimeoutMinutes;
    const isMaxAttemptsReached = currentPromptAttemptCount >= maxPromptAttempts;
    const isReportReceived = reportReceivedTime !== null && reportReceivedTime !== undefined;
    const isWithin30MinutesBeforeMeeting = minutesUntilMeeting <= 30 && minutesUntilMeeting >= 0;
  
    const shouldContinuePrompting =
      !isTimeoutExceeded &&
      !isMaxAttemptsReached &&
      !isReportReceived &&
      !isWithin30MinutesBeforeMeeting;
  
    let recommendedAction: "continue" | "stop" | "notifyManager" = "continue";
  
    if (isReportReceived) {
      recommendedAction = "stop";
    } else if (isTimeoutExceeded && isMaxAttemptsReached) {
      recommendedAction = "notifyManager";
    } else if (isTimeoutExceeded || isMaxAttemptsReached || isWithin30MinutesBeforeMeeting) {
      recommendedAction = "stop";
    }
  
    return {
      shouldContinuePrompting,
      isTimeoutExceeded,
      isMaxAttemptsReached,
      recommendedAction,
      elapsedMinutes,
      minutesUntilMeeting,
    };
  }
  return { judgePromptLoopTermination };
})();
export const judgePromptLoopTermination = __aivicBundle_104_judgePromptLoopTermination.judgePromptLoopTermination;
/* AIVIC_FUNCTION_BUNDLE_END owner=judgePromptLoopTermination */

