const __aivicBundle_105_determinePushLoopTermination = (() => {
  function determinePushLoopTermination(loopState: {
    push_target_member_id?: string | null;
    push_attempt_count: number;
    max_push_attempts: number;
    last_push_sent_at: Date;
    push_interval_minutes: number;
    attemptCount?: number;
    maxAttempts?: number;
    lastAttemptTime?: Date;
    currentTime?: Date;
    deadlineTime?: Date;
    reportReceived?: boolean;
  }): {
    shouldTerminate: boolean;
    reason: string;
    nextAction: 'continue' | 'stop' | 'escalate';
  } {
    // Validate required field: push_target_member_id
    if (loopState.push_target_member_id === null || loopState.push_target_member_id === undefined) {
      throw new Error('催促対象部員IDが指定されていません');
    }
  
    // Normalize field names (support both snake_case and camelCase)
    const attemptCount = loopState.push_attempt_count ?? loopState.attemptCount ?? 0;
    const maxAttempts = loopState.max_push_attempts ?? loopState.maxAttempts ?? 3;
    const lastAttemptTime = loopState.last_push_sent_at ?? loopState.lastAttemptTime ?? new Date();
    const currentTime = loopState.currentTime ?? new Date();
    const deadlineTime = loopState.deadlineTime ?? new Date(currentTime.getTime() + 60 * 60 * 1000);
    const pushIntervalMinutes = loopState.push_interval_minutes ?? 5;
    const reportReceived = loopState.reportReceived ?? false;
  
    // Calculate elapsed time since last attempt (in minutes)
    const elapsedMinutes = (currentTime.getTime() - lastAttemptTime.getTime()) / (1000 * 60);
  
    // Calculate time remaining until deadline (in minutes)
    const minutesUntilDeadline = (deadlineTime.getTime() - currentTime.getTime()) / (1000 * 60);
  
    // Decision logic
    if (reportReceived) {
      return {
        shouldTerminate: true,
        reason: 'Report received',
        nextAction: 'stop',
      };
    }
  
    if (attemptCount >= maxAttempts) {
      return {
        shouldTerminate: true,
        reason: 'Max attempts reached',
        nextAction: 'escalate',
      };
    }
  
    if (minutesUntilDeadline <= 0) {
      return {
        shouldTerminate: true,
        reason: 'Deadline exceeded',
        nextAction: 'escalate',
      };
    }
  
    if (elapsedMinutes < pushIntervalMinutes) {
      return {
        shouldTerminate: false,
        reason: 'Interval not yet elapsed',
        nextAction: 'continue',
      };
    }
  
    return {
      shouldTerminate: false,
      reason: 'Within attempt limit and time',
      nextAction: 'continue',
    };
  }
  return { determinePushLoopTermination };
})();
