    const { loop_start_time, current_time, unprompted_user_id, dept_head_id, threshold_minutes, send_mail_called, is_active, promptStartTime, maxPromptAttempts, promptTimeoutMinutes, currentPromptAttemptCount, morningMeetingStartTime, currentTime } = context;
  
