/* AIVIC_FUNCTION_BUNDLE_START owner=verifyReportArrivalStatus exports=verifyReportArrivalStatus */
const __aivicBundle_140_verifyReportArrivalStatus = (() => {
  function verifyReportArrivalStatus(params: any): any {
    // expectedCount の検証
    if (params.expectedCount === null || params.expectedCount === undefined) {
      return {
        error: true,
        errorCode: 'MISSING_EXPECTED_COUNT',
        errorMessage: '期待報告人数が指定されていません',
      };
    }
  
    // 権限チェック（user_role が manager でない場合）
    if (params.user_role && params.user_role !== 'manager') {
      return {
        success: false,
        status_code: 403,
        error_message: 'このページへのアクセス権限がありません',
      };
    }
  
    // 通常の到着状況検証ロジック
    const submittedReports = params.submittedReports || [];
    const allTeamMembers = params.allTeamMembers || [];
    const reportDeadline = params.reportDeadline;
  
    
  
    const arrivedMembers: Array<{ id: string; name: string }> = [];
    const delayedMembers: Array<{ id: string; name: string; delayMinutes: number }> = [];
    const missingMembers: Array<{ id: string; name: string }> = [];
  
    for (const member of allTeamMembers) {
      const submitted = submittedReports.find((r: any) => r.memberId === member.id);
  
      if (!submitted) {
        missingMembers.push({ id: member.id, name: member.name });
      } else if (reportDeadline && submitted.submittedAt > reportDeadline) {
        const delayMs = submitted.submittedAt.getTime() - reportDeadline.getTime();
        const delayMinutes = Math.ceil(delayMs / (1000 * 60));
        delayedMembers.push({
          id: member.id,
          name: member.name,
          delayMinutes,
        });
      } else {
        arrivedMembers.push({ id: member.id, name: member.name });
      }
    }
  
    return {
      arrivedCount: arrivedMembers.length,
      missingCount: missingMembers.length,
      delayedCount: delayedMembers.length,
      missingMembers,
      delayedMembers,
    };
  }
  return { verifyReportArrivalStatus };
})();
