const __aivicBundle_155_validateReportContent = (() => {
  function validateReportContent(input: SendConfirmationEmailsInput): {
    status: string;
    message: string;
    isComplete?: boolean;
    missingFields?: Array<string>;
    validationMessage?: string;
  } {
    // Extract report content fields from various possible input shapes
    const yesterday =
      input.yesterday_accomplishment ||
      input.yesterdayAccomplishment ||
      input.yesterday_achievements ||
      input.yesterday_result ||
      input.yesterdayWork ||
      input.report_yesterday ||
      input.yesterday ||
      "";
  
    const today =
      input.todayPlan ||
      input.today_plans ||
      input.today_plan_text ||
      input.todayWork ||
      input.report_today ||
      input.today ||
      "";
  
    const issues =
      input.currentIssues ||
      input.current_issue ||
      input.challenges ||
      input.report_issue ||
      input.issues ||
      "";
  
    // Check if all three fields are empty or whitespace-only
    const yesterdayEmpty = !yesterday || yesterday.trim() === "";
    const todayEmpty = !today || today.trim() === "";
    const issuesEmpty = !issues || issues.trim() === "";
  
    const allEmpty = yesterdayEmpty && todayEmpty && issuesEmpty;
  
    if (allEmpty) {
      return {
        status: "warning",
        message:
          "昨日やったこと、今日やること、抱えている課題のいずれか1つ以上の入力が必須です",
        isComplete: false,
        missingFields: ["昨日やったこと", "今日やること", "抱えている課題"],
        validationMessage:
          "不足項目: 昨日やったこと, 今日やること, 抱えている課題",
      };
    }
  
    // Collect missing fields
    const missingFields: Array<string> = [];
    if (yesterdayEmpty) {
      missingFields.push("昨日やったこと");
    }
    if (todayEmpty) {
      missingFields.push("今日やること");
    }
    if (issuesEmpty) {
      missingFields.push("抱えている課題");
    }
  
    if (missingFields.length > 0) {
      return {
        status: "warning",
        message: `不足項目: ${missingFields.join(", ")}`,
        isComplete: false,
        missingFields,
        validationMessage: `不足項目: ${missingFields.join(", ")}`,
      };
    }
  
    // All fields are present
    return {
      status: "success",
      message: "形式OK",
      isComplete: true,
      missingFields: [],
      validationMessage: "形式OK",
    };
  }
  return { validateReportContent };
})();
export const validateReportContent = __aivicBundle_155_validateReportContent.validateReportContent;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReportContent */

