    allUserIds?: string[];
    triggerTime?: string;
    unreportedMemberIds?: string[];
    unreportedMemberNames?: string[];
    unreportedMemberEmails?: string[];
    managerEmail?: string;
    reportDate?: string;
    currentTime?: Date;
