    const allUserIds = input.allUserIds ?? [];
  
    const unreportedUserIds = allUserIds.filter(
      (userId) => !reportedUserIds.includes(userId)
    );
    const unreportedCount = unreportedUserIds.length;
  
    if (unreportedCount === 0) {
      return {
        skipped: true,
        unreportedCount: 0,
        emailsSent: 0,
        reason: `未報告者は${unreportedCount}名のためスキップされました`,
        remindersSent: 0,
        remindersSkipped: 0,
        status: 'skipped',
      };
    }
  
    const maxRetries = input.maxRetries ?? 3;
  
    if (maxRetries <= 0) {
      return {
        skipped: true,
        unreportedCount,
        emailsSent: 0,
        reason: `最大リトライ回数に達したためスキップされました`,
        remindersSent: 0,
        remindersSkipped: unreportedCount,
        status: 'max_retries_reached',
      };
    }
  
    const emailsSent = unreportedCount;
  
    return {
      skipped: false,
      unreportedCount,
      emailsSent,
      reason: `${unreportedCount}名の未報告者に催促メールを送信しました`,
      remindersSent: emailsSent,
      remindersSkipped: 0,
      status: 'completed',
    };
