/* AIVIC_FUNCTION_BUNDLE_START owner=sendReportMissingReminderNotification exports=sendReportMissingReminderNotification */
const __aivicBundle_176_sendReportMissingReminderNotification = (() => {
  async function sendReportMissingReminderNotification(
    missingMembers: any,
    departmentHeadEmail: string
  ): Promise<{ success: boolean; message: string }> {
    // Handle both array and object input formats
    let membersArray: Array<{ user_id?: string; memberId?: string; member_name?: string; memberName?: string; email: string }> = [];
    
    if (Array.isArray(missingMembers)) {
      membersArray = missingMembers;
    } else if (missingMembers && typeof missingMembers === 'object' && 'missingMembers' in missingMembers) {
      membersArray = missingMembers.missingMembers;
    }
  
    // Deduplicate members by user_id/memberId
    const uniqueMembersMap = new Map<string, { user_id?: string; memberId?: string; member_name?: string; memberName?: string; email: string }>();
    
    for (const member of membersArray) {
      const id = member.user_id || member.memberId || member.email;
      if (!uniqueMembersMap.has(id)) {
        uniqueMembersMap.set(id, member);
      }
    }
  
    const uniqueMembers = Array.from(uniqueMembersMap.values());
  
    // Build member name list
    const memberNames = uniqueMembers
      .map(m => m.member_name || m.memberName)
      .filter((name): name is string => !!name)
      .join('、');
  
    // Prepare email content
    const subject = `【重要】未報告部員への通知`;
    const body = `以下の部員から報告がありません：\n${memberNames}\n\nお手数ですが、ご確認ください。`;
  
    // Send email via fetch (matching test expectations)
    try {
      const response = await fetch('/api/send-email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          to: departmentHeadEmail,
          subject: subject,
          body: body,
        }),
      });
  
      const result = await response.json();
      return result;
    } catch (error) {
      return { success: false, message: 'Failed to send email' };
    }
  }
  return { sendReportMissingReminderNotification };
})();
export const sendReportMissingReminderNotification = __aivicBundle_176_sendReportMissingReminderNotification.sendReportMissingReminderNotification;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendReportMissingReminderNotification */

