const __aivicBundle_177_sendReminderEmail = (() => {
  function sendReminderEmail(input: ReminderEmailInput): ReminderEmailResult {
    if (input["reportDeadlineTime"] === undefined || input["reportDeadlineTime"] === null) { throw new Error("reportDeadlineTime is required"); }
    if (input["employeeName"] === undefined || input["employeeName"] === null) { throw new Error("employeeName is required"); }
    if (input["departmentId"] === undefined || input["departmentId"] === null) { throw new Error("departmentId is required"); }
    if (input["departmentName"] === undefined || input["departmentName"] === null) { throw new Error("departmentName is required"); }
    if (input["managerEmail"] === undefined || input["managerEmail"] === null) { throw new Error("managerEmail is required"); }
    if (input["managerName"] === undefined || input["managerName"] === null) { throw new Error("managerName is required"); }
    const { employeeId, employeeEmail, currentTime, attemptCount, maxAttempts } = input;
  
    // メールアドレスの妥当性チェック
    if (!employeeEmail || employeeEmail.trim() === '') {
      return {
        success: false,
        emailSent: false,
        sentAt: null,
        attemptNumber: attemptCount,
        nextRetryTime: null,
        errorMessage: '送信者メールアドレスが不正です',
        employeeId,
        status: 'failed',
      };
    }
  
    // 最大試行回数に達した場合
    if (attemptCount >= maxAttempts) {
      return {
        success: false,
        emailSent: false,
        sentAt: null,
        attemptNumber: attemptCount,
        nextRetryTime: null,
        errorMessage: '最大試行回数に達しました',
        employeeId,
        status: 'skipped',
      };
    }
  
    // 遅延時間を計算（分単位）
    
  
    // メール送信成功時の処理
    // 次回再試行時刻は5分後に設定
    const nextRetryTime = new Date(currentTime.getTime() + 5 * 60 * 1000);
  
    return {
      success: true,
      emailSent: true,
      sentAt: currentTime,
      attemptNumber: attemptCount,
      nextRetryTime,
      errorMessage: null,
      employeeId,
      status: 'sent',
    };
  }
  return { sendReminderEmail };
})();
